tape( 'if provided an increment between successive values of `IPIV` equal to `0`, the function returns the input matrix unchanged (column-major)', opts, function test( t ) {
	var expected;
	var IPIV;
	var data;
	var out;
	var A;

	data = COL_MAJOR;

	A = new Float64Array( data.A );
	IPIV = new Int32Array( data.IPIV );

	expected = new Float64Array( data.A );

	out = dlaswp( data.order, data.N, A, data.LDA, data.k1, data.k2, IPIV, 0 );
	t.strictEqual( out, A, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});
